        val targetIP = intent.getStringExtra("target")
        val openPorts = intent.getStringArrayListExtra("openPorts")

        // Analyze the network scan results
        analyzeNetworkScanResults(openPorts)
    }

    private fun analyzeNetworkScanResults(openPorts: List<Int>) {
        if (openPorts.isEmpty()) {
            val alertMessage = "No open ports found."
            findViewById<TextView>(R.id.networkScanResult).text = alertMessage
            return
        }

        val analysisResults = mutableListOf<String>()

        for (port in openPorts) {
            analysisResults.add("Open port: $port")
        }

        // Convert the list of results to a JSON string and display it on the screen
